export const BODY: string = "\n<p>صنع كولاج صور عمل قصير: تختار بضع صور وتختار تصميمًا وترتبها وتصدّر صورة واحدة. يمر هذا الدليل بكل خطوة بالترتيب، من اختيار الصور إلى مشاركة الكولاج المنتهي.</p>\n<p>قبل أن تبدأ تحتاج شيئًا واحدًا فقط: الصور التي تريد دمجها. أربع إلى تسع صور قوية بضوء متشابه تعطي أفضل كولاج. ومجموعة صور من رحلة أو حدث أو نطاق منتجات تعمل جيدًا.</p>\n<p>يقوم <a href=\"/ar/munshi-kulaj-as-suwar/\">منشئ كولاج الصور</a> بالعمل في متصفحك. لا شيء يُرفع إلى خادم ولا حساب، والتصدير مجاني. اتبع الخطوات أدناه وستكون لديك كولاج منتهٍ في دقائق معدودة.</p>\n<h2 id=\"step-1-choose-your-photos\">الخطوة 1: اختر صورك</h2>\n<p>اختر الصور التي تنتمي معًا: كولاج يروي قصة صغيرة، فيجب أن تشترك الصور في موضوع: رحلة أو عيد ميلاد أو نطاق منتجات أو لقاء عائلي. والصور غير المترابطة تبدو عشوائية مهما كان التصميم جيدًا.</p>\n<p>اختر أربع إلى تسع صور: أربع تملأ شبكة 2 في 2 دون مشاكل، وتسع تملأ شبكة 3 في 3. وأقل من أربع يترك خلايا فارغة، وأكثر من تسع يجعل كل صورة صغيرة جدًا. واختر صورًا بضوء ولون متشابهين: مجموعة فيها صورة داكنة وضبابية تجذب النظر إلى الصورة الضعيفة، بينما مجموعة بضوء متسق تبدو كمجموعة مقصودة.</p>\n<p>اختر صورة رئيسية: صورة قوية ستصبح الصورة المميزة، مكبرة فوق البقية، فاختر الصورة التي تمثل المجموعة أفضل. والرئيسية غالبًا هي أوضح صورة وأكثرها إشراقًا.</p>\n<h2 id=\"step-2-upload-the-photos\">الخطوة 2: ارفع الصور</h2>\n<p>افتح <a href=\"/ar/munshi-kulaj-as-suwar/\">منشئ الكولاج</a> واسحب صورك إلى منطقة الرفع، أو انقر لاختيارها من جهازك. ويمكنك رفعها كلها دفعة واحدة، وستضعها الأداة في الشبكة بترتيب الرفع.</p>\n<p>تقبل الأداة ملفات JPG وPNG وWebP وHEIC وGIF وBMP وSVG حتى 20 MB لكل ملف: صور الهاتف واللقطات والرسوم تعمل، ومزيج صيغ في كولاج جيد. ورفع خمس صور أو أكثر يختار تلقائيًا شبكة 3 في 3، بينما أربع أو أقل تختار تلقائيًا شبكة 2 في 2. وإذا رفعت صورًا أقل من خلايا الشبكة، تنتظر الخلايا الفارغة صورًا أكثر.</p>\n<p>وإذا رفعت الصورة الخطأ، أزلها دون البدء من جديد: تتيح لك الأداة إزالة صورة واحدة من خلية واستبدالها، فالخطأ يكلف ثوانٍ لا إعادة بناء الكولاج كله.</p>\n<h2 id=\"step-3-pick-a-layout\">الخطوة 3: اختر تصميمًا</h2>\n<p>اختر تصميم شبكة أو شريط: شبكة 2 في 2 تناسب أربع صور، وشبكة 3 في 3 تناسب تسعًا، وشريط عمودي يناسب تسلسلًا يُقرأ من أعلى إلى أسفل، وشريط أفقي يناسب خطًا زمنيًا.</p>\n<p>تناسب الشبكات مجموعات حيث كل صورة تهم بالتساوي: رحلة أو حدث أو نطاق منتجات. والشكل المربع يناسب الخلاصات والإعلانات، والخلايا المتساوية تعطي كل صورة وزنًا متساويًا. وتناسب الأشرطة التسلسلات والمقارنات: شريط عمودي يُقرأ كقصة، ما يناسب يومًا بالترتيب. وشريط أفقي يُقرأ كخط زمني، ما يناسب قبل وبعد.</p>\n<p>غيّر التصميم بحرية بعد الرفع: تبقى الصور في أماكنها وتُعاد ترتيب الخلايا، فتستطيع مقارنة شبكة وشريط في ثوانٍ. والتصميم الذي يُقرأ أفضل من بعيد هو عادة الاختيار الصحيح.</p>\n<h2 id=\"step-4-arrange-the-photos\">الخطوة 4: رتّب الصور</h2>\n<p>اسحب صورة فوق خلية أخرى لتبديلهما على سطح المكتب، أو المس للتحديد والمس مجددًا للتبديل على هاتف: التبديل فوري، وتستطيع إعادة الترتيب بقدر ما تريد قبل التصدير.</p>\n<p>ضع الصورة الرئيسية في أبرز خلية: في شبكة 2 في 2، هي الخلية العلوية اليسرى، التي تراها العين أولًا. وفي شبكة 3 في 3، تجذب الخلية الوسطى النظر، فالرئيسية تنتمي هناك. ووازن الضوء والظلام في الشبكة: صورة داكنة بجانب أخرى داكنة تخلق زاوية ثقيلة، بينما صورة داكنة بجانب فاتحة توازن الكولاج. ووزّع الصور الساطعة بالتساوي بدل تكديسها في جانب واحد.</p>\n<p>جرّب ترتيبات عدة قبل أن تقرر: صورة تبدو ضائعة في خلية قد تثبّت الكولاج في خلية أخرى، وتبديل يستغرق ثانية قد يغيّر التوازن كله. وثق بعينك: إذا بدا الترتيب صحيحًا من بعيد، فهو صحيح.</p>\n<h2 id=\"step-5-feature-a-photo\">الخطوة 5: أبرز صورة</h2>\n<p>اجعل الصورة الرئيسية أكبر من البقية بضبط التقسيمات: اسحب خط تقسيم لتكبير الخلية الرئيسية وتصغير جيرانها، ما يمنح الكولاج نقطة محورية واضحة.</p>\n<p>اختر المميزة بالجودة إضافة إلى الموضوع: يجب أن تكون الرئيسية أحدة صورة وأكثرها إشراقًا في المجموعة، لأن تكبير صورة ضعيفة يجذب الانتباه فقط إلى عيوبها. وصورة قوية مكبرة ترفع الكولاج كله. وأبقِ المميزة صورة واحدة: خليتان كبيرتان تتنافسان والهرمية تنكسر، فكبّر خلية واحدة بوضوح فوق البقية واترك الأخريات متساوية. ومميزة واحدة هي القاعدة.</p>\n<p>وإذا أصبحت التقسيمات غير متساوية وتريد البدء من جديد، أعدها إلى شبكة موحدة: تعيد الأداة التقسيمات إلى خلايا متساوية، فتستطيع تجربة ترتيب مميز آخر.</p>\n<h2 id=\"step-6-adjust-gaps-and-corners\">الخطوة 6: اضبط الفجوات والزوايا</h2>\n<p>حدد الفجوة بين الخلايا: فجوة صفر تعطي كولاجًا متواصلًا دون حدود، حيث تلمس الصور بعضها وتشكل صورة واحدة متواصلة. وفجوة مرئية تفصل الصور إلى إطارات مميزة.</p>\n<p>حدد نصف قطر زاوية الخلايا: نصف قطر صغير ينعّم الكولاج ويناسب المنشورات الاجتماعية، بينما الزوايا المربعة تبدو رسمية وتناسب المطبوعات والعروض. والفجوة ونصف قطر الزاوية مستقلان، فتستطيع دمجهما بحرية: فجوة واسعة بزوايا مربعة تبدو كجدار معرض، بينما فجوة ضيقة بزوايا مدورة تبدو ناعمة وحديثة.</p>\n<p>يظهر لون الخلفية عبر الفجوات، فاختر الفجوة والخلفية كزوج: فجوة بيضاء فوق خلفية بيضاء تبدو كحد نظيف، بينما لون علامة في الفجوات يربط الكولاج بحملة.</p>\n<h2 id=\"step-7-set-the-background\">الخطوة 7: حدد الخلفية</h2>\n<p>اختر لون الخلفية من الإعدادات السريعة: الأبيض هو الافتراضي والخيار الأكثر أمانًا: يبقي الكولاج نظيفًا ويناسب أي خلاصة أو صفحة، ويجعل الصور بارزة.</p>\n<p>لون علامة يحوّل الكولاج إلى رسم مصمم: اللون في الفجوات يربط الكولاج بحملة، ومجموعة كولاجات بنفس اللون تشكل سلسلة مميزة. واستخدمه عندما يكون الكولاج جزءًا من هوية أكبر. وملصقات PNG الشفافة الموضوعة في خلايا تُظهر لون الخلفية خلفها: ملصق فوق خلفية بيضاء يُقرأ كقص نظيف، بينما ملصق فوق خلفية داكنة قد يفقد حوافه.</p>\n<p>أبقِ الخلفية بسيطة: خلفية تنافس الصور تجذب النظر إلى الفجوات بدل الصور، ولون فجوة ساطع بين صور باهتة يجعل الكولاج يبدو صاخبًا.</p>\n<h2 id=\"step-8-choose-the-canvas-size\">الخطوة 8: اختر حجم اللوحة</h2>\n<p>اختر حجم لوحة ونسبة للوجهة: المربع يناسب الخلاصات والإعلانات والمصغرات. والعمودي يناسب القصص وخلفيات شاشة الهاتف. والعريض يناسب اللافتات والعروض.</p>\n<p>تصل دقة التصدير إلى 4000 بكسل، كبيرة بما يكفي للطباعة: اختر تصديرًا كبيرًا عندما قد يُطبع الكولاج، ومعتدلًا عندما سيُنشر على الإنترنت فقط. وراجع المعاينة بالنسبة المختارة: كولاج يبدو متوازنًا كمربع قد يبدو ممدودًا كعمودي، لأن الخلايا تغيّر شكلها. واضبط الترتيب بعد تغيير النسبة.</p>\n<p>وإذا لم تعرف أين سيُستخدم الكولاج، اختر المربع: إنه أكثر شكل مرونة، ويُقص بشكل متوقع في كل مكان، ويعمل كمصغرة وصورة إعلان ومنشور خلاصة دون تغيير.</p>\n<h2 id=\"step-9-preview-the-collage\">الخطوة 9: اعرض معاينة للكولاج</h2>\n<p>انظر إلى المعاينة الكاملة قبل التصدير: تحقق من أن كل صورة في الخلية الصحيحة، وأن الصورة الرئيسية بارزة، وأن الفجوات متساوية، وأن لون الخلفية يبدو كما قصدت.</p>\n<p>راجع كل خلية بحثًا عن قصاصات سيئة: ضبط تغطية قد يقطع وجهًا أو وسم منتج أو سطر نص عند حافة صورة. وغيّر الضبط إلى احتواء لأي خلية تفقد تفاصيل مهمة. وانظر إلى الكولاج على هاتفك إذا كان للتواصل الاجتماعي: لون فجوة يبدو لطيفًا على شاشة سطح مكتب قد يبدو قويًا على شاشة هاتف، وكولاج يبدو متوازنًا كبيرًا قد يبدو مزدحمًا صغيرًا.</p>\n<p>قارن الكولاج أيضًا بحجم صغير: قلّص عرضك إلى حجم مصغرة وتحقق من أن الكولاج ما زال يُقرأ. كولاج يعمل فقط بالحجم الكامل يفشل كمنشور خلاصة.</p>\n<h2 id=\"step-10-export-and-share\">الخطوة 10: صدّر وشارك</h2>\n<p>اختر صيغة التصدير: يناسب JPG الصور الفوتوغرافية وأي كولاج يكون فيه ملف صغير مهمًا، مثل منشور اجتماعي. ويناسب PNG كولاجات بنص حاد وألوان مسطحة وشفافية، لأنه يحافظ على كل حافة نظيفة.</p>\n<p>انقر تنزيل فيُحفظ الكولاج المنتهي على جهازك: يعكس اسم الملف ضبط الكولاج، فتستطيع تمييز النسخ عندما تصدّر عدة نسخ. وافتح الملف المنزّل مرة قبل مشاركته: تحقق من أن كل خلية صحيحة وأن لا شيء قُص خطأ. وشارك الكولاج كصورة واحدة: ارفعه إلى خلاصة اجتماعية أو أرفقه برسالة أو أضفه إلى إعلان. والكولاج ملف واحد، فيُنشر مثل أي صورة أخرى، والصور الفردية لا تُنشر منفصلة.</p>\n<p>احتفظ بالصور المصدر إضافة إلى الكولاج المنتهي: إذا احتجت لاحقًا نسبة أخرى أو تصميمًا آخر أو صورة مصححة، تتيح لك الصور إعادة البناء في دقائق. وكولاج مسطح مصدّر لا يمكن فكه.</p>\n<h2 id=\"collages-for-print\">كولاجات للطباعة</h2>\n<p>كولاج للطباعة يحتاج تصديرًا كبيرًا: اختر أقصى دقة، حتى 4000 بكسل، ليبقى الطباعة حادًا بالحجم الذي تريده. وكولاج مصدّر للتواصل الاجتماعي سيبدو ناعمًا عند طباعته كبيرًا.</p>\n<p>اختر PNG لأحدة طباعة، أو JPG عالي الجودة لطباعة فوتوغرافية: يحافظ PNG على الحواف والنص حادًا، بينما يضغط JPG الصور بكفاءة. وكلاهما يعمل؛ اختر بحسب ما في الكولاج. وراجع النسبة مقابل حجم الورق أو الإطار: كولاج مربع يناسب إطارًا مربعًا، بينما كولاج عمودي يناسب طباعة فوتوغرافية قياسية. وفرق صغير في النسبة يعني قصًا أو حدودًا بيضاء.</p>\n<p>اطبع اختبارًا صغيرًا أولًا عندما يهم الكولاج، مثل هدية أو طباعة مؤطرة: يكشف الاختبار تغيرات اللون ومشاكل الحدة التي تخفيها الشاشة، ويكلف أقل بكثير من إعادة طباعة كبيرة.</p>\n<h2 id=\"fixing-a-collage-that-looks-off\">كيف تصلح كولاجًا يبدو سيئًا</h2>\n<p>كولاج يبدو سيئًا غالبًا له أحد مشاكل أربعة: صورة ضعيفة أو قص سيئ أو ترتيب غير متوازن أو لون فجوة ينافس الصور: أصلحها بهذا الترتيب، بدءًا بالصورة.</p>\n<p>استبدل الصورة الأضعف أولًا: صورة داكنة أو ضبابية أو خارج الموضوع تجذب النظر أينما كانت، ولا ترتيب يستطيع إخفاءها. وبدّلها بصورة أقوى من نفس المجموعة. ثم راجع القصاصات: وجه مقطوع عند حافة خلية أو موضوع مضغوط بالضبط يفسد الخلية. وغيّر الضبط إلى احتواء لتلك الخلية، أو اختر صورة أخرى لها، وستبدو الخلية صحيحة فورًا.</p>\n<p>بعدها، أعد توازن الترتيب: افصل الصور الساطعة وانقل الرئيسية إلى الخلية المميزة ووزّع الصور الداكنة بالتساوي. وتبديل واحد غالبًا يصلح كولاجًا بدا مكسورًا. وأخيرًا، بسّط الفجوات والخلفية: لون فجوة ساطع أو خلفية مزدحمة قد يجعل كولاجًا جيدًا يبدو صاخبًا. وضع الفجوات على الأبيض والزوايا على نصف قطر صغير، وسيهدأ الكولاج.</p>\n<h2 id=\"quick-reference\">مرجع سريع: قائمة تحقق كولاج</h2>\n<p>اختر أربع إلى تسع صور قوية بضوء متشابه وارفعها واختر شبكة أو شريطًا. ورتّب بالسحب أو المس للتبديل وكبّر الصورة الرئيسية، وحدد الفجوات والزوايا والخلفية.</p>\n<p>اختر نسبة لوحة للوجهة وصدّر JPG للصور وPNG للرسوم، وراجع كل خلية بحثًا عن قصاصات سيئة بالحجم الكامل وبحجم مصغرة. واحفظ الصور المصدر مع الكولاج المنتهي.</p>\n<p>للدليل الكامل، اقرأ <a href=\"/ar/blog/dalil-munshi-kulaj-as-suwar/\">الدليل الكامل لمنشئ كولاج الصور</a>، ولأفكار التصميم اقرأ <a href=\"/ar/blog/takhtitat-kulaj-wa-shabakat-wa-lawhat-mizaj/\">تصاميم كولاج: شبكات ولوحات مزاج وقصص</a>. وأنشئ كولاجك من <a href=\"/ar/munshi-kulaj-as-suwar/\">منشئ كولاج الصور</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أختار أي صور تدخل في كولاج؟","answer":"اختر صورًا تشترك في موضوع، مثل رحلة أو حدث أو نطاق منتجات، واختر أربع إلى تسع من أقواها. والصور بضوء ولون متشابهين تبدو كمجموعة، بينما مزيج بضوء مختلط يبدو عشوائيًا."},{"question":"ماذا يحدث إذا رفعت صورًا أقل من خلايا التصميم؟","answer":"تنتظر الخلايا الفارغة صورًا أكثر، ويمكنك إضافتها لاحقًا. ويمكنك أيضًا التبديل إلى تصميم أصغر، مثل شبكة 2 في 2 لأربع صور، فلا توجد خلايا فارغة. ولا تصدّر بخلايا فارغة."},{"question":"هل يمكنني نقل صورة إلى خلية أخرى؟","answer":"نعم، اسحب صورة فوق خلية أخرى لتبديلهما على سطح المكتب، أو المس للتحديد والمس مجددًا للتبديل على هاتف أو جهاز لوحي. وتستطيع إعادة الترتيب بقدر ما تريد قبل التصدير."},{"question":"هل أحفظ كولاجي كـJPG أم PNG؟","answer":"استخدم JPG لكولاجات الصور وأي صورة يكون فيها ملف صغير مهمًا، مثل منشور اجتماعي. واستخدم PNG لكولاجات بنص حاد أو ألوان مسطحة أو شفافية، لأن PNG يحافظ على كل حافة نظيفة."},{"question":"كيف أطبع كولاجي؟","answer":"صدّر بأكبر دقة، حتى 4000 بكسل، وطابق نسبة اللوحة مع حجم الورق أو الإطار. واختر PNG لأحدة طباعة أو JPG عالي الجودة لطباعة فوتوغرافية، واطبع اختبارًا صغيرًا أولًا للمطبوعات المهمة."},{"question":"هل يمكنني إنشاء كولاج على هاتفي؟","answer":"نعم، يعمل منشئ الكولاج في متصفح الهواتف والأجهزة اللوحية: ارفع من معرض صورك والمس لتبديل الصور بين الخلايا ونزّل الكولاج المنتهي. والمس للتبديل يحل محل السحب على شاشات اللمس."}];
